using ForensicEdu.Mobile.Controls;
using ForensicEdu.Mobile.Core.Models;
using ForensicEdu.Mobile.Core.Services;
namespace ForensicEdu.Mobile.Pages;
public sealed class CertificatesPage:AcademyPage
{
 public CertificatesPage(IServiceProvider s):base(s,"Certificados"){Shell.SetNavBarIsVisible(this,false);}
 protected override async void OnAppearing(){base.OnAppearing();if(!RequireAccount())return;await Run(async()=>{var certificates=await Api.AllAsync<Certificate>("student/certificates");Body.Clear();Header("ACREDITACIÓN","Mis certificados","Tus logros y su validación pública.");foreach(var c in certificates){var stack=Ui.Stack(Ui.Eyebrow(c.StatusLabel),Ui.Text(c.CourseTitle,23,true),Ui.Text(c.StudentFullName,15,true),Ui.Text($"{c.AcademicHours} horas · {c.FinalGrade}/20\n{c.IssueDate.ToLocalTime():dd/MM/yyyy} · {c.CertificateCode}",12,false,"Muted"));using var generator=new QRCoder.QRCodeGenerator();using var data=generator.CreateQrCode(new Uri(Api.BaseAddress,"certificates/verify/"+Id(c.CertificateCode)).AbsoluteUri,QRCoder.QRCodeGenerator.ECCLevel.Q);using var qr=new QRCoder.PngByteQRCode(data);var png=qr.GetGraphic(6);stack.Add(new Image{Source=ImageSource.FromStream(()=>new MemoryStream(png)),HeightRequest=180,WidthRequest=180,BackgroundColor=Colors.White});stack.Add(Ui.Action("Verificar certificado",()=>Push(new VerificationPage(Services,c.CertificateCode)),true));stack.Add(Ui.Action("Compartir diploma PDF",()=>Run(async()=>{var bytes=await Api.BytesAsync($"certificates/download/{Id(c.CertificateCode)}/pdf");var path=Path.Combine(FileSystem.CacheDirectory,"certificado-"+Guid.NewGuid().ToString("N")+".pdf");await File.WriteAllBytesAsync(path,bytes);await Share.Default.RequestAsync(new ShareFileRequest{Title="Certificado académico",File=new ShareFile(path,"application/pdf")});})));Body.Add(Ui.Card(stack,true));}if(certificates.Count==0)Body.Add(Ui.Text("Aquí aparecerán tus certificados al aprobar tus cursos.",14,false,"Muted"));Body.Add(Ui.Action("Validar otro certificado",()=>Push(new VerificationPage(Services)),true));});}
}
